// This shader is part of my learning of shaders. At this time I'm exploring the
// drawing of curves defined implicitly. Spoiler alert: this is by no means trivial.
// 
// For the distance to implicity curve approximation, see:
// Taubin, Gabriel - Distance Approximations for Rasterizing Implicit Curves
// ACM Transactions on Graphics, Vol. 13, No. 1, January 1994.

#define PI 3.1415926

// First order approximation, works.
float folio(vec2 p) { 
    float a = 1.5 * iTime / 100.0;
    // Compute the first order approximation of the distance, which is |f|/|grad f|:
    float f = p.x * p.x * p.x + p.y * p.y * p.y - 3.0 * a * p.x * p.y;
    vec2 grad = vec2(3.0 * p.x * p.x - 3.0 * a * p.y, 3.0 * p.y * p.y - 3.0 * a * p.x);
    float dist = abs(f) / max(length(grad), 0.0001);
    return dist;
}

// 2nd-order has problems at (0,0)
float folio2(vec2 p) { 
    float a = 1.5 * iTime / 100.0;
    float f = p.x * p.x * p.x + p.y * p.y * p.y - 3.0 * a * p.x * p.y;
    vec2 grad = vec2(3.0 * p.x * p.x - 3.0 * a * p.y, 3.0 * p.y * p.y - 3.0 * a * p.x);
    float gradLength = max(length(grad), 0.0001); // Avoid division by zero

    // Normalize the gradient
    vec2 v = grad / gradLength;

    // First-order approximation
    float d_first = abs(f) / gradLength;

    // Test if first-order estimate is valid
    vec2 testPoint = p - d_first * v; // Move along the gradient
    float f_test = pow(testPoint.x, 3.0) + pow(testPoint.y, 3.0) - 3.0 * testPoint.x * testPoint.y;
    float epsilon = 0.001; // Tolerance

    if (abs(f_test) < epsilon) {
        // First-order is sufficient
        return d_first;
    }

    // Compute Hessian components
    float hxx = 6.0 * p.x;
    float hyy = 6.0 * p.y;
    float hxy = -3.0 * a;

    // Compute curvature term (v^T H v)
    float curvature = v.x * (hxx * v.x + hxy * v.y) + v.y * (hxy * v.x + hyy * v.y);

    // Second-order distance approximation
    float distance = abs(f) / sqrt(gradLength * gradLength + f * curvature / (gradLength * gradLength));
    return distance;
}

// 3rd-order improves problem at (0,0), but not much.
float folio3(vec2 p) { 
    float a = 1.5;
    // Implicit function
    float f = p.x * p.x * p.x + p.y * p.y * p.y - 3.0 * a * p.x * p.y;

    // Gradient
    vec2 grad = vec2(3.0 * p.x * p.x - 3.0 * a * p.y, 3.0 * p.y * p.y - 3.0 * a * p.x);
    float gradLength = max(length(grad), 0.0001);

    // Normalize gradient
    vec2 v = grad / gradLength;

    // Hessian
    float hxx = 6.0 * p.x;
    float hyy = 6.0 * p.y;
    float hxy = -3.0 * a;

    float curvature = v.x * (hxx * v.x + hxy * v.y) + v.y * (hxy * v.x + hyy * v.y);

    // Third-Order Derivatives (Tensor)
    float txxx = 6.0, tyy = 6.0; // Only pure third derivatives matter here
    float thirdOrderTerm = v.x * v.x * v.x * txxx + v.y * v.y * v.y * tyy;

    // Third-order distance approximation
    float distance = abs(f) / sqrt(
        gradLength * gradLength +
        f * curvature / gradLength +
        0.5 * f * thirdOrderTerm / (gradLength * gradLength)
    );

    return distance;
}

// Better aproximate the distance at singular points. See Taubin.
vec2 weightedLeastSquaresTangent(vec2 p, float a, float sigma) {
    // Constants for Gaussian weights
    const int NUM_SAMPLES = 8; // Number of samples around the point
    vec2 offsets[NUM_SAMPLES] = vec2[](
        vec2(1.0, 0.0), vec2(-1.0, 0.0), vec2(0.0, 1.0), vec2(0.0, -1.0),
        vec2(0.707, 0.707), vec2(-0.707, 0.707), vec2(0.707, -0.707), vec2(-0.707, -0.707)
    );

    // Accumulators for weighted tangent calculation
    vec2 weightedGradientSum = vec2(0.0);
    float weightSum = 0.0;

    // Loop over neighboring points
    for (int i = 0; i < NUM_SAMPLES; i++) {
        // Neighboring point
        vec2 neighbor = p + sigma * offsets[i];

        // Compute the gradient of f(x, y) at the neighbor
        vec2 grad = vec2(
            3.0 * neighbor.x * neighbor.x - 3.0 * a * neighbor.y,
            3.0 * neighbor.y * neighbor.y - 3.0 * a * neighbor.x
        );

        // Compute the weight (Gaussian falloff based on distance)
        float dist2 = dot(offsets[i], offsets[i]); // Squared distance
        float weight = exp(-dist2 / (2.0 * sigma * sigma)); // Gaussian weight

        // Accumulate weighted gradients
        weightedGradientSum += weight * grad;
        weightSum += weight;
    }

    // Normalize the weighted sum to compute the tangent direction
    vec2 tangent = normalize(weightedGradientSum / weightSum);

    // Handle edge cases (e.g., when all gradients vanish)
    if (length(weightedGradientSum) < 0.0001) {
        tangent = vec2(1.0, 0.0); // Default tangent direction
    }

    return tangent;
}


// Uses the above solution for singular points and works best.
float folio4(vec2 p) { 
    float a = 2.0+0.8*sin(iTime*6.28/4.0);
    // Compute the implicit function value
    float f = p.x * p.x * p.x + p.y * p.y * p.y - 3.0 * a * p.x * p.y;

    // Compute the gradient
    vec2 grad = vec2(
        3.0 * p.x * p.x - 3.0 * a * p.y,
        3.0 * p.y * p.y - 3.0 * a * p.x
    );

    // Handle singularities with the weighted least-squares tangent
    if (length(grad) < 0.001) {
        grad = weightedLeastSquaresTangent(p, a, 0.1); // Use tangent approximation
    }

    // Compute the first-order distance
    float dist = abs(f) / max(length(grad), 0.0001); // Avoid division by zero
    return dist;
}

// Here is another implicit curve that is not polynomial - lots of connected components!
float curve1(vec2 p) {
    float f = sin(p.x + p.y) - cos(p.x * p.y) + 1.0;
    vec2 grad = vec2(cos(p.x + p.y) + sin(p.x * p.y) * p.y, cos(p.x + p.y) + sin(p.x * p.y) * p.x);
    float dist = abs(f) / max(length(grad), 0.0001);    
    return dist;
}

// Implicit function for the 4th-order curve
float curve(vec2 p) {
    return 3.0 * pow(p.y, 4.0) - 5.0 * pow(p.y, 3.0) + p.x * p.x;
}

// Gradient of the curve
vec2 curveGradient(vec2 p) {
    return vec2(
        2.0 * p.x,                           // ∂f/∂x
        12.0 * pow(p.y, 3.0) - 15.0 * pow(p.y, 2.0) // ∂f/∂y
    );
}

// First-order distance approximation
float curve2(vec2 p) {
    // Compute the implicit function value
    float f = curve(p);

    // Compute the gradient
    vec2 grad = curveGradient(p);

    // Compute the first-order distance
    return abs(f) / max(length(grad), 0.0001); // Avoid division by zero
}

// Weighted least-squares tangent for singular points
vec2 weightedLeastSquaresTangent1(vec2 p, float sigma) {
    // Constants for Gaussian weights
    const int NUM_SAMPLES = 8; // Number of samples around the point
    vec2 offsets[NUM_SAMPLES] = vec2[](
        vec2(1.0, 0.0), vec2(-1.0, 0.0), vec2(0.0, 1.0), vec2(0.0, -1.0),
        vec2(0.707, 0.707), vec2(-0.707, 0.707), vec2(0.707, -0.707), vec2(-0.707, -0.707)
    );

    // Accumulators for weighted tangent calculation
    vec2 weightedGradientSum = vec2(0.0);
    float weightSum = 0.0;

    // Loop over neighboring points
    for (int i = 0; i < NUM_SAMPLES; i++) {
        // Neighboring point
        vec2 neighbor = p + sigma * offsets[i];

        // Compute the gradient of f(x, y) at the neighbor
        vec2 grad = curveGradient(neighbor);

        // Compute the weight (Gaussian falloff based on distance)
        float dist2 = dot(offsets[i], offsets[i]); // Squared distance
        float weight = exp(-dist2 / (2.0 * sigma * sigma)); // Gaussian weight

        // Accumulate weighted gradients
        weightedGradientSum += weight * grad;
        weightSum += weight;
    }

    // Normalize the weighted sum to compute the tangent direction
    vec2 tangent = normalize(weightedGradientSum / weightSum);

    // Handle edge cases (e.g., when all gradients vanish)
    if (length(weightedGradientSum) < 0.0001) {
        tangent = vec2(1.0, 0.0); // Default tangent direction
    }

    return tangent;
}

// Distance function with singular point treatment
float curve3(vec2 p) {
    const float sigma = 0.1;
    // Compute the implicit function value
    float f = curve(p);

    // Compute the gradient
    vec2 grad = curveGradient(p);

    // Handle singularities with the weighted least-squares tangent
    if (length(grad) < 0.001) {
        grad = weightedLeastSquaresTangent1(p, sigma); // Use tangent approximation
    }

    // Compute the first-order distance
    return abs(f) / max(length(grad), 0.0001); // Avoid division by zero
}

const float par_a = 0.25;
const float par_b = 0.0;
const float par_c = 0.0;

// Implicit function for a parabola
float parabola_implicit(vec2 p) {
  float c = -9.0+20.0*mod(iTime/4.0,1.0);
    return mod(par_a*p.x*p.x + par_b*p.x + par_c + c - p.y, 5.0); // mod replicates curve
}

// Gradient of the parabola
vec2 parabola_gradient(vec2 p) {
    return vec2(
        2.0*par_a*p.x + par_b,   // ∂f/∂x
        -1.0                     // ∂f/∂y
    );
}

float parabola(in vec2 p)
{
    p = abs(p);
    float a = 1.5 * iTime / 100.0;
    // Compute the first order approximation of the distance, which is |f|/|grad f|:
    float f = parabola_implicit(p);
    vec2 grad = parabola_gradient(p);
    float dist = abs(f) / max(length(grad), 0.0001);
    return dist;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize coordinates to range (-1, 1)
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0;
    uv.x *= iResolution.x / iResolution.y; // Maintain aspect ratio

    // Scale the coordinates to fit the curve nicely
    vec2 p = 8.0 * uv;
    float theta = PI/4.0+PI/4.0*sin(iTime/10.0);
    mat2 r = mat2(cos(theta),-sin(theta),sin(theta),cos(theta));
    mat2 r2 = mat2(cos(PI/4.0),-sin(PI/4.0),sin(PI/4.0),cos(PI/4.0));

    // Evaluate the folio function
    float d = min(folio4(r2*p), curve1(r*p));
    d = min(d, curve3(p));
    d = min(d, parabola(p));
    // float d = curve2(-0.5*r*p);

    // Smooth transition for anti-aliasing
    float thickness = 0.02; // Base thickness
    float aa = 0.005;       // Anti-aliasing width
    float intensity = smoothstep(thickness + aa, thickness - aa, d);
    // intensity = smoothstep(0.2, 0.0, d); // For glow

    // Set color based on intensity
    vec3 col = vec3(intensity);

    // Output final color
    fragColor = vec4(col, 1.0);
}
